/usr/bin/bash -lc "python - <<'PY'
from datetime import datetime
values=['2026-06-01','2026-06-01 00:00:00','2026-06-01T00:00:00+00:00','2026-06-01T01:00:00+02:00']
for v in values:
    try: print(v, '->', datetime.fromisoformat(v).isoformat())
    except Exception as e: print(v, type(e).__name__, e)
